// Índice de dificultad de Fitts, formulación de Shannon: ID = log2(D / W + 1), en bits.
// D: distancia al centro del blanco; W: su tamaño en la dirección del movimiento.
const dificultad = (D, W) => Math.log2(D / W + 1);

const D = 600; // el puntero (o el pulgar) viene de 600 px de distancia
for (const [nombre, W] of [["enlace chico", 16], ["botón de 20 px", 20], ["botón de 44 px", 44], ["botón de 52 px", 52], ["botón a todo el ancho", 358]]) {
  console.log(nombre.padEnd(22), "W =", String(W).padStart(3), "px   ID =", dificultad(D, W).toFixed(2), "bits");
}
// Misma pieza, pero acercándola: ¿qué pesa más, el tamaño o la distancia?
console.log("---");
console.log("W = 20 px, D = 600 px  ->", dificultad(600, 20).toFixed(2));
console.log("W = 20 px, D = 100 px  ->", dificultad(100, 20).toFixed(2));
console.log("W = 100 px, D = 600 px ->", dificultad(600, 100).toFixed(2));

// Ley de Hick-Hyman con opciones igual de probables: T = b * log2(n + 1).
// b depende de la persona y de la tarea; acá lo dejamos como unidad (b = 1) para comparar.
const T = (n) => Math.log2(n + 1);
const base = T(2);
for (const n of [1, 2, 4, 8, 16, 32]) {
  console.log("n =", String(n).padStart(2), " log2(n+1) =", T(n).toFixed(2), " respecto de 2 opciones:", (T(n) / base).toFixed(2), "veces");
}
// Dividir 16 opciones en 4 grupos de 4: elegir grupo y después elegir dentro.
console.log("16 de una vez:", T(16).toFixed(2), "| 4 grupos + 4 opciones:", (T(4) + T(4)).toFixed(2));
